import { DialogHeader } from '@kerfjs/ui/dialog-header';

export function mountMasterDetailDialog(dialog: HTMLDialogElement, app: { select(id: string): void; close(): void; confirm(): void }) {
  dialog.innerHTML = `<form method="dialog" class="master-detail-dialog"><header data-header></header><div class="dialog-body"><nav aria-label="Items"><ul data-items></ul></nav><section aria-label="Item details"><p data-summary></p><dl data-metadata></dl></section></div><footer><button type="button" data-cancel>Cancel</button><button type="button" data-confirm>Choose item</button></footer></form>`;
  DialogHeader({ target: dialog.querySelector('[data-header]')!, title: 'Choose an item', description: 'Select an item to review its details.' });
  const items = dialog.querySelector('[data-items]')!;
  for (const item of [{ id: 'a', name: 'Alpha' }, { id: 'b', name: 'Beta' }]) { const button = document.createElement('button'); button.type = 'button'; button.textContent = item.name; button.setAttribute('aria-pressed', String(item.id === 'a')); button.onclick = () => app.select(item.id); const li = document.createElement('li'); li.append(button); items.append(li); }
  dialog.querySelector('[data-cancel]')!.addEventListener('click', app.close);
  dialog.querySelector('[data-confirm]')!.addEventListener('click', app.confirm);
}

